-- 添加全平台导览长帖
-- 用法: wrangler d1 execute cqufic-db --remote --file=migrations/add-platform-guide-post.sql

INSERT OR IGNORE INTO posts (id, title, category, summary, content, date, is_pinned) VALUES (
  'platform-full-guide-2026',
  '写给新同学：CQU FIC 全平台导览（2026 完整版）',
  '通知公告',
  '平台每一块的用途、入口、数据来源、隐私声明、彩蛋……一篇看完，整个网站怎么用都清楚。',
  '<p>你好，新同学，欢迎来到 <strong>CQU FIC —— 重庆大学新生服务融合中心平台</strong>。这是一份“长一点”的使用导览，把网站每一块的用途、入口和注意事项一次讲清楚——看完这篇，你就能自如地用上整个平台。</p><h3>一、我们为什么做这个平台</h3><p>每年开学前后，新生都会被零散信息包围：录取通知里的报到流程、辅导员群里的预报到通知、学长学姐口中的“必看清单”、官网角落里的细则……信息散在不同地方、版本各异，新生很容易踩坑。</p><p>我们是几位重大在校学生，自己也走过这一遭，所以自发做了这个站，把“从入学到熟悉校园”这段路上需要的信息<strong>统一整合、官方核对、持续更新</strong>。平台 100% 公益，不收费、不商业化、不要你注册账号。</p><h3>二、整体功能地图</h3><p>首页“你需要什么？”区域是入口，四大板块：</p><ul><li><strong>入学流程</strong>：时间线呈现，从录取到正式开学每一步该做什么</li><li><strong>信息汇总库</strong>：21 个主题，覆盖学习、生活、校园资讯、实用工具</li><li><strong>超好用地图</strong>：虎溪、沙坪坝（A/B 区）、华岩 C 区、两江新校区交互式校园地图</li><li><strong>包罗万象社区</strong>：你正在看的这个论坛，新生交流提问</li></ul><p>另有“反馈与建议”板块，提供“问题反馈 / 功能建议 / 体验评价”三种入口，后文会讲它们的区别。</p><h3>三、入学流程</h3><p>覆盖从收到录取通知书到正式开学的全部关键节点：激活统一身份认证（authserver.cqu.edu.cn）、智慧学工线上预报到、体检缴费、本科报到日（2025-2026 学年 9 月 8-9 日）、军训动员（9 月 14 日）、医保参保（约 10-11 月截止）、户籍迁移（11 月 10 日截止）、正式开课等。</p><p><strong>用法：</strong>第一次打开就完整读一遍，把所有“截止日期”加进手机日历——错过医保参保，你这一学年门诊报销就没了。</p><h3>四、信息汇总库（21 个主题）</h3><p>这是平台最重量级的部分，分四类：</p><p><em>学习相关</em>（5）：选课指南、学业规划、图书馆资源、在线学习、教师联系。<br><em>生活服务</em>（5）：宿舍分配、食堂导航、校园交通、生活购物、医疗服务。<br><em>校园资讯</em>（5）：校历安排、校园新闻、社团活动、竞赛信息、重要通知。<br><em>实用工具</em>（6）：证件办理、网络服务、打印服务、账号管理、常见问题、校园地图入口。</p><p>每个主题点进去都有：<strong>概要 + 关键要点 + 行动步骤 + 检查清单 + 注意事项 + 常见问答</strong>。例如选课指南会告诉你 my.cqu.edu.cn 的预选 / 正选 / 退补选三轮怎么走、跨校区课程要预留 40-60 分钟通勤；医疗服务会告诉你大学生医保约 380 元/年、什么时候截止、校医院电话 023-65678120、就在校北门旁。</p><p><strong>用法：</strong>把它当工具书，需要时搜索关键字（如“宿舍”“选课”），不必一次读完。</p><h3>五、超好用地图</h3><p>基于 Mapbox 的交互式校园地图，覆盖虎溪（科学城）、沙坪坝 A 区 / B 区、华岩 C 区、两江新校区。可以：</p><ul><li>切换校区查看不同区域</li><li>查找食堂、宿舍园区、教学楼、图书馆、医院的具体位置</li><li>规划报到日的行李路线</li></ul><p>第一次到校特别推荐先打开看一遍——虎溪校区很大，先熟悉布局能省很多脚程。</p><h3>六、包罗万象社区（论坛）</h3><p>就是你现在看到的这个板块。规则简单：</p><ul><li><strong>不用注册、不用登录</strong>，填昵称、写内容就能发</li><li>可以填邮箱或手机号——仅管理员可见，用于必要时联系你，<strong>不会公开显示</strong></li><li>可以直接回复别人的留言，互助答疑</li><li>含敏感词、违规内容会被过滤，多次违规会被限制留言</li></ul><p><strong>用法：</strong>问问题前先去信息汇总库搜一下，多数常见问题那里已有答案；发帖时选对分类，方便其他同学找到。</p><h3>七、反馈、建议、评价——三个入口的区别</h3><ul><li><strong>问题反馈</strong>：平台 bug、内容错误、某个功能用不了 → 走这里。我们会跟进修复</li><li><strong>功能建议</strong>：希望平台增加 XX 功能 → 走这里。我们会评估并放进迭代计划</li><li><strong>体验评价</strong>：整体评分 + 一句感想，公开展示，帮我们和其他同学了解平台口碑</li></ul><h3>八、这些信息从哪来、准不准</h3><p>所有内容以<strong>重庆大学官方渠道</strong>为第一来源：cqu.edu.cn 主站、my.cqu.edu.cn 教务、casp.cqu.edu.cn 办事大厅、各学院官网，以及“重大虎溪”等官方公众号。社区补充信息部分来自学生维护的 <em>CQU-openlib（重庆大学资源共享计划，非官方）</em>，引用时已标注。</p><p>我们持续对照官方源核对，但学校政策会调整。如果你发现任何条目过时或不准，<strong>请走“问题反馈”告诉我们</strong>，会尽快修订。涉及缴费、学籍、考试这类高敏感信息，务必再去官方网站二次确认——一切以官方为准。</p><h3>九、隐私与公益声明</h3><ul><li>留言的昵称和正文公开；<strong>联系方式仅管理员可见，绝不外传</strong></li><li>平台不放任何广告、不商业化、不收费</li><li>不收集浏览行为做画像、不卖数据</li><li>只有当你主动提交反馈 / 评价时，相关信息才会进入我们的数据库</li></ul><h3>十、关于我们</h3><p>团队由几位重大在校学生组成，自发开发、自费维护。做这件事的动力很简单：自己当年没人告诉这些，希望后来的新同学少走弯路。如果你想加入维护、贡献内容，去“功能建议”留言告诉我们就好。</p><h3>十一、彩蛋：试试点 5 次校徽</h3><p>每个页面顶栏中间那个校徽，<strong>连续点 5 次</strong>会有惊喜……自己去发现吧。</p><h3>十二、遇到问题怎么办</h3><p>三种渠道，按情况选：</p><ul><li><strong>内容 / 功能有问题</strong>：问题反馈页面</li><li><strong>有更好的想法</strong>：功能建议</li><li><strong>急或想公开讨论</strong>：在论坛直接发帖，管理员和其他同学都能看到</li></ul><h3>最后</h3><p>送你一句重大校训：<strong>耐劳苦、尚俭朴、勤学业、爱国家</strong>。也送你一句陪你度过这段忙乱时光的话——别慌，你不是一个人在面对这些；遇到不懂的就问，问到对的人就能解决。</p><p>欢迎你成为重大人，我们在这里等你 💙</p><p>—— CQU FIC 团队</p>',
  '2026-05-28',
  1
);
